import { override } from 'flarum/common/extend';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
const EXT_ID = 'ramon-auth-modals';

// As configurações salvam a cada alteração, então o botão de salvar padrão sobra.
export default function addHideExtensionSubmitButton() {
  override(ExtensionPage.prototype, 'submitButton', function (original) {
    if (this.extension && this.extension.id === EXT_ID) return null;
    return original();
  });
}